// Documents with charts, generated by code: the frame of a chart in the text
// (<w:drawing> with a <c:chart r:id>), the chart part beside the document
// (word/charts/chartN.xml) and the workbook Word embeds for it
// (word/embeddings/*.xlsx), which no test here ever opens.

import { ZipArchive } from '../src/zip';
import { catAx, chartXml, group, NS_C, numRef, ser, solid, spPr, strRef, valAx } from './chart-fixtures';
import type { DocxSpec } from './docx-fixtures';

const XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
const NS_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const NS_PKG_REL = 'http://schemas.openxmlformats.org/package/2006/relationships';
const PX = 9525;

const graphic = (rel: string) =>
  `<a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="${NS_C}">` +
  `<c:chart xmlns:c="${NS_C}" xmlns:r="${NS_REL}" r:id="${rel}"/></a:graphicData></a:graphic>`;

/** The <w:drawing> of a chart that stands in its line: size in px. */
export const inlineChartDrawing = (rel: string, width: number, height: number, docPr = 'id="7" name="Chart 1"') =>
  `<w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${width * PX}" cy="${height * PX}"/>` +
  `<wp:docPr ${docPr}/><wp:cNvGraphicFramePr/>${graphic(rel)}</wp:inline></w:drawing>`;

/** A run that holds a chart in its line. */
export const inlineChart = (rel: string, width: number, height: number, docPr?: string) => `<w:r>${inlineChartDrawing(rel, width, height, docPr)}</w:r>`;

/** A run that holds a chart text flows around: `x` and `y` in px from the column and the paragraph. */
export const floatingChart = (rel: string, x: number, y: number, width: number, height: number, wrap = '<wp:wrapSquare wrapText="bothSides"/>') =>
  '<w:r><w:drawing><wp:anchor distT="0" distB="0" distL="114300" distR="114300" simplePos="0" relativeHeight="2" behindDoc="0" locked="0" layoutInCell="1" allowOverlap="1">' +
  `<wp:simplePos x="0" y="0"/><wp:positionH relativeFrom="column"><wp:posOffset>${x * PX}</wp:posOffset></wp:positionH>` +
  `<wp:positionV relativeFrom="paragraph"><wp:posOffset>${y * PX}</wp:posOffset></wp:positionV>` +
  `<wp:extent cx="${width * PX}" cy="${height * PX}"/>${wrap}<wp:docPr id="8" name="Chart 2"/><wp:cNvGraphicFramePr/>${graphic(rel)}</wp:anchor></w:drawing></w:r>`;

export interface ColumnsSpec {
  /** "RRGGBB" the columns are filled with. Default 00B050. */
  color?: string;
  values?: (number | null)[];
  /** Without the cached values: the series only names its cells. */
  uncached?: boolean;
  /** Elements of <c:chart> before the plot area (a title). */
  head?: string;
  /** The element name of the chart type. Default "barChart"; "contourChart" stands for a type that is not drawn. */
  type?: string;
  /** More series, after the first: whole <c:ser> elements. */
  more?: string;
  /** With `uncached`: the name of the series is a reference without a cached text. */
  nameRef?: string;
}

/** A chart part: one series of columns over a value axis from 0 to 100, so that the height of a column is its value. */
export function columnsChart(spec: ColumnsSpec = {}): string {
  const values = spec.values || [50, 100, 25];
  const cat = spec.uncached ? '<c:strRef><c:f>Sheet1!$A$2:$A$4</c:f></c:strRef>' : strRef('Sheet1!$A$2:$A$4', values.map((_value, i) => `c${i + 1}`));
  const val = spec.uncached ? '<c:numRef><c:f>Sheet1!$B$2:$B$4</c:f></c:numRef>' : numRef('Sheet1!$B$2:$B$4', values);
  return chartXml({
    head: spec.head,
    plot:
      group(spec.type || 'barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat, val, props: spPr(solid(spec.color || '00B050')), tx: spec.nameRef ? `<c:strRef><c:f>${spec.nameRef}</c:f></c:strRef>` : undefined }) + (spec.more || ''), '<c:gapWidth val="100"/>') +
      catAx() +
      valAx('<c:majorGridlines/>', '<c:orientation val="minMax"/><c:max val="100"/><c:min val="0"/>'),
    after: '<c:externalData r:id="rId1"><c:autoUpdate val="0"/></c:externalData>',
  });
}

/** Stands for the workbook Word embeds beside a chart: a zip that is no workbook, so that opening it would fail loudly. */
export async function embeddedWorkbook(): Promise<Uint8Array> {
  const zip = new ZipArchive();
  zip.set('not-a-workbook.txt', new TextEncoder().encode('The embedded workbook of a chart is never opened.'));
  return zip.write();
}

export interface ChartPartSpec {
  /** Relationship id in the part that holds the frame. */
  rel: string;
  /** The chart part, whole. A Uint8Array is written as it is (for parts that are not XML). */
  xml: string | Uint8Array;
  /** The bytes of the embedded workbook of the chart. Default: embeddedWorkbook(), a zip that is no workbook. */
  workbook?: Uint8Array;
  /** The name of the embedded workbook under word/embeddings/. Default "Microsoft_Excel_Sheet<n>.xlsx". */
  embedding?: string;
  /** The relationship of the chart part to its workbook, whole (<Relationship .../>); '' for none. */
  bookRel?: string;
}

/**
 * What a DocxSpec needs for the charts: relationships of the document part and the
 * parts themselves, each chart with its relationships and its embedded workbook.
 * Charts are numbered from `first` (word/charts/chart<n>.xml).
 */
export async function chartParts(charts: ChartPartSpec[], first = 1): Promise<Required<Pick<DocxSpec, 'rels' | 'parts'>>> {
  const rels: NonNullable<DocxSpec['rels']> = [];
  const parts: NonNullable<DocxSpec['parts']> = [];
  const workbook = await embeddedWorkbook();
  charts.forEach((chart, i) => {
    const n = first + i;
    rels.push([chart.rel, 'chart', `charts/chart${n}.xml`]);
    parts.push([`word/charts/chart${n}.xml`, chart.xml]);
    const embedding = chart.embedding || `Microsoft_Excel_Sheet${n}.xlsx`;
    const rel = chart.bookRel !== undefined ? chart.bookRel : `<Relationship Id="rId1" Type="${NS_REL}/package" Target="../embeddings/${embedding}"/>`;
    parts.push([`word/charts/_rels/chart${n}.xml.rels`, `${XML}<Relationships xmlns="${NS_PKG_REL}">${rel}</Relationships>`]);
    // Two charts may share one workbook: the entry is written once.
    if (!parts.some(([name]) => name === `word/embeddings/${embedding}`)) parts.push([`word/embeddings/${embedding}`, chart.workbook || workbook]);
  });
  return { rels, parts };
}

/** The relationships part of a header, footer or notes part: [zip entry name, content] for DocxSpec.parts. */
export const partRels = (part: string, rels: [id: string, type: string, target: string, external?: boolean][]): [string, string] => [
  `word/_rels/${part}.rels`,
  `${XML}<Relationships xmlns="${NS_PKG_REL}">` +
    rels.map(([id, type, target, external]) => `<Relationship Id="${id}" Type="${NS_REL}/${type}" Target="${target}"${external ? ' TargetMode="External"' : ''}/>`).join('') +
    '</Relationships>',
];
